using UnityEngine; using TMPro;
public class UIManager:MonoBehaviour{public TextMeshProUGUI rotationDisplay,positionDisplay,speedDisplay,statusDisplay,distanceDisplay,angleDisplay;public DebugRotator targetRotator;public UsefulMath usefulMath;void Update(){if(targetRotator!=null){if(rotationDisplay)rotationDisplay.text="Rotation: "+targetRotator.currentRotation.ToString("F1")+"°";if(positionDisplay)positionDisplay.text="Position: "+targetRotator.objectPosition.ToString("F2");if(speedDisplay)speedDisplay.text="Speed: "+targetRotator.rotationSpeed.ToString("F1");if(statusDisplay)statusDisplay.text="Status: "+(targetRotator.isRotating?"Rotating":"Stopped");}if(usefulMath!=null){if(distanceDisplay)distanceDisplay.text="Distance: "+usefulMath.distanceToFallingCube.ToString("F2");if(angleDisplay)angleDisplay.text="Angle: "+usefulMath.angleToFallingCube.ToString("F1")+"°";}}}
